// Shared contracts for every Roster module. Shapes follow docs/DESIGN.md §"Data model".
// Change minimally, and say so in your PR.

/** Evidence level printed next to every claim: A observational, B controlled replay, C forward. */
export type EvidenceLevel = "A" | "B" | "C";
export const EVIDENCE_LEVELS: readonly EvidenceLevel[] = ["A", "B", "C"] as const;

/** Failure taxonomy (DESIGN.md §"Grade"). */
export enum FailureCode {
  /** edited tests */
  F1 = "F1",
  /** never ran tests */
  F2 = "F2",
  /** suite regression */
  F3 = "F3",
  /** stopped early */
  F4 = "F4",
  /** loop, timeout or turn cap */
  F5 = "F5",
  /** environment or setup error; the task is excluded and resampled */
  F6 = "F6",
  /** off-scope edits */
  F7 = "F7",
}

/** Where a session row came from. */
export type SessionSource = "branch" | "git-refs";

/** One agent session, aggregated over all checkpoints it appears in. Table `sessions`. */
export interface Session {
  id: string;
  repo: string;
  checkpoint_id: string;
  harness: string;
  /** Resolved model, or "unknown" when neither metadata nor transcript records it. */
  model: string;
  /** sha256 of the normalised rules file; null when unknown, never a guess. */
  rules_hash: string | null;
  setup_id: string | null;
  tokens_in: number;
  tokens_out: number;
  cache_read: number;
  cache_write: number;
  /** null when the model's price is unknown. */
  cost_usd: number | null;
  n_user_prompts: number;
  first_prompt: string;
  /** null when no commit carries this session's checkpoint trailer. */
  commit_sha: string | null;
  started_at: string;
  ended_at: string;
  files: string[];
  entire_url: string | null;
  source: SessionSource;
}

export type OutcomeStatus = "mature" | "too_young";
export type Tercile = 1 | 2 | 3;

/** Score of one session. Metrics are null when status is too_young. Table `outcomes`. */
export interface Outcome {
  session_id: string;
  status: OutcomeStatus;
  survival: number | null;
  reverted: boolean | null;
  rework_human: number | null;
  rework_agent: number | null;
  unattended: boolean | null;
  tests_at_commit: boolean | null;
  difficulty: number | null;
  tercile: Tercile | null;
}

/** Setup = harness + model + rules_hash. Table `setups`. */
export interface Setup {
  id: string;
  harness: string;
  model: string;
  rules_hash: string | null;
  rules_path: string | null;
  label: string;
}

/** Coordinator plan. Table `plans`; `json` holds the serialised PlanBody. */
export interface Plan {
  id: string;
  review_id: string;
  json: string;
  rationale: string;
  created_at: string;
}

/** Body of plan.json (DESIGN.md §"Plan (coordinator)"). */
export interface PlanBody {
  suspect: string | null;
  /** Session ids, ≤ 12, stratified by tercile. */
  tasks: string[];
  /** Setup ids, ≤ 3 per iteration. */
  candidates: string[];
  budget_usd: number;
  stop_rules: string[];
  rationale: string;
}

export type ReplayVerdict =
  | "agent_error"
  | "no_changes"
  | "hidden_tests_failed"
  | "suite_failed"
  | "guardrail_flagged"
  | "pass";

/** One replay attempt of a task under a setup. Table `replays`. */
export interface Replay {
  id: string;
  plan_id: string;
  task_session_id: string;
  setup_id: string;
  attempt: number;
  isolation_proof: string;
  turns: number | null;
  duration_ms: number | null;
  cost_usd: number | null;
  hidden_pass: boolean | null;
  suite_pass: boolean | null;
  scope_ok: boolean | null;
  judge_equiv: boolean | null;
  failure_codes: FailureCode[];
  verdict: ReplayVerdict;
  transcript_ref: string | null;
  trace_url: string | null;
}

export type GateVerdict = "promote" | "reject";

/** Table `gate_decisions`. */
export interface GateDecision {
  id: string;
  plan_id: string;
  candidate: string;
  verdict: GateVerdict;
  reasons: string[];
  trace_url: string | null;
}

/** One pre-registered forward task run through both setups. Table `forward_pairs`. */
export interface ForwardPair {
  task_id: string;
  setup_old: string;
  setup_new: string;
  pass_old: boolean;
  pass_new: boolean;
  cost_old: number | null;
  cost_new: number | null;
  /** Which setup's change was merged, if any. */
  merged: "old" | "new" | null;
  /** Blind label assignment, e.g. { X: "old", Y: "new" }. */
  blind_labels: Record<string, "old" | "new">;
  seed: number;
}

export type ReviewLabel = "suspect" | "no_suspect" | "insufficient_data";

/** Difficulty-matched scorecard result (DESIGN.md §"Difficulty and review"). */
export interface Review {
  id: string;
  repo: string;
  created_at: string;
  label: ReviewLabel;
  /** Setup id when label is "suspect". */
  suspect: string | null;
  /** Mantel–Haenszel odds ratio, setup X vs the rest, stratified by tercile. */
  odds_ratio: number | null;
  ci95: [number, number] | null;
  p_value: number | null;
  evidence_level: EvidenceLevel;
}
// neatlogs instrumentation of Roster's own runs (DESIGN.md §"Observability (neatlogs)").
// One review = one trace: WORKFLOW root → AGENT coordinator → TOOL steps and attempts, plus a GUARDRAIL gate.
// Without NEATLOGS_API_KEY every call is a no-op and the wrapped work still runs.
import { EvidenceLevel, FailureCode } from "../types.ts";
import { type SpanAttrs, type SpanKind, toAttributes } from "./attributes.ts";

export type { SpanAttrs, SpanKind } from "./attributes.ts";

/** What the SDK hands a span body. `traceId` is set only when the SDK exposes OpenTelemetry-style span context. */
export interface ObsSpan {
  setAttribute(key: string, value: string | number | boolean): void;
  traceId?: string;
}

/** The subset of the neatlogs SDK this module uses (docs.neatlogs.com/sdk/typescript). */
interface NeatlogsSdk {
  init(opts: { apiKey?: string; workflowName: string }): Promise<unknown>;
  trace<T>(opts: { name: string; kind: SpanKind }, fn: (span: ObsSpan) => Promise<T>): Promise<T>;
  flush(): Promise<void>;
}

// Resolved at runtime, not via a static import: the package is optional, and a missing one must be a no-op.
const SDK_MODULE = "neatlogs";

const NOOP_SPAN: ObsSpan = { setAttribute() {} };

let sdk: NeatlogsSdk | null = null;
let sessionId: string | undefined;
let warned = false;

function warnOnce(msg: string): void {
  if (warned) return;
  warned = true;
  console.warn(`[roster] observability disabled: ${msg}`);
}

/**
 * Starts neatlogs for this process. Resolves to true when tracing is live.
 * With NEATLOGS_API_KEY unset (or the SDK not installed) it resolves to false and warns once.
 */
export async function initObs(opts: { workflowName: string }): Promise<boolean> {
  const apiKey = process.env.NEATLOGS_API_KEY;
  if (!apiKey) {
    warnOnce("NEATLOGS_API_KEY is not set");
    return false;
  }
  try {
    const mod = (await import(SDK_MODULE)) as NeatlogsSdk;
    await mod.init({ apiKey, workflowName: opts.workflowName });
    sdk = mod;
    return true;
  } catch (err) {
    warnOnce(`could not load ${SDK_MODULE} (${err instanceof Error ? err.message : String(err)})`);
    return false;
  }
}

/** True once initObs has enabled tracing. */
export function obsEnabled(): boolean {
  return sdk !== null;
}

/** Tags the current review. Every span opened after this carries it as `session.id`. */
export function setSession(reviewId: string): void {
  sessionId = reviewId;
}

/**
 * Runs `fn` inside one span of the given kind. The span is nested under whatever span is active,
 * so calling withSpan inside a WORKFLOW body builds the tree. Errors propagate after the span closes.
 */
export async function withSpan<T>(
  kind: SpanKind,
  name: string,
  attrs: SpanAttrs,
  fn: (span: ObsSpan) => Promise<T>,
): Promise<T> {
  if (!sdk) return fn(NOOP_SPAN);
  const client = sdk;
  return client.trace({ name, kind }, async (span) => {
    for (const [key, value] of Object.entries(toAttributes(attrs))) span.setAttribute(key, value);
    if (sessionId !== undefined) span.setAttribute("session.id", sessionId);
    return fn(span);
  });
}

/** Outcome of one replay attempt, recorded as a finished TOOL span. */
export interface AttemptOutcome {
  failureCode?: FailureCode | FailureCode[];
  evidenceLevel?: EvidenceLevel;
  costUsd?: number;
}

/** Records one replay attempt as a TOOL span carrying its outcome. The span has no body work of its own. */
export async function recordAttempt(spanAttrs: SpanAttrs, attempt: number, outcome: AttemptOutcome): Promise<void> {
  await withSpan("TOOL", `replay attempt ${attempt}`, { ...spanAttrs, ...outcome, attempt }, async () => undefined);
}

/** Sends buffered spans. Call once before the process exits. A no-op when tracing is off. */
export async function flushObs(): Promise<void> {
  if (sdk) await sdk.flush();
}
// roster.* span attribute names (DESIGN.md §"Observability (neatlogs)"). Names are a contract; do not rename.
import { EvidenceLevel, FailureCode } from "../types.ts";

export const ATTR = {
  setup: "roster.setup",
  task: "roster.task",
  attempt: "roster.attempt",
  failureCode: "roster.failure_code",
  evidenceLevel: "roster.evidence_level",
  repo: "roster.repo",
  costUsd: "roster.cost_usd",
} as const;

/** The span kinds the design names: WORKFLOW root, AGENT coordinator, TOOL steps, GUARDRAIL gate. */
export type SpanKind = "WORKFLOW" | "AGENT" | "TOOL" | "GUARDRAIL";

/** Attributes a Roster span can carry. Every field is optional; unset fields are not written. */
export interface SpanAttrs {
  setup?: string;
  task?: string;
  attempt?: number;
  failureCode?: FailureCode | FailureCode[];
  evidenceLevel?: EvidenceLevel;
  repo?: string;
  costUsd?: number;
}

export type AttrValue = string | number;

/** Maps Roster's camelCase fields to the exact `roster.*` attribute names, dropping unset fields. */
export function toAttributes(attrs: SpanAttrs): Record<string, AttrValue> {
  const out: Record<string, AttrValue> = {};
  if (attrs.setup !== undefined) out[ATTR.setup] = attrs.setup;
  if (attrs.task !== undefined) out[ATTR.task] = attrs.task;
  if (attrs.attempt !== undefined) out[ATTR.attempt] = attrs.attempt;
  if (attrs.failureCode !== undefined) {
    out[ATTR.failureCode] = Array.isArray(attrs.failureCode) ? attrs.failureCode.join(",") : attrs.failureCode;
  }
  if (attrs.evidenceLevel !== undefined) out[ATTR.evidenceLevel] = attrs.evidenceLevel;
  if (attrs.repo !== undefined) out[ATTR.repo] = attrs.repo;
  if (attrs.costUsd !== undefined) out[ATTR.costUsd] = attrs.costUsd;
  return out;
}
import rows from "./prices.json";

// Prices are USD per 1M tokens, taken from src/price/prices.json.
// A null price means "not confirmed", so a session that uses it has a null cost. We never guess.

export type PriceRow = {
  id: string;
  model_pattern: string;
  input: number | null;
  output: number | null;
  cache_read: number | null;
  cache_write: number | null;
  cache_write_1h?: number | null;
  max_prompt_tokens?: number;
  min_prompt_tokens?: number;
  source_url: string | null;
  checked_on: string;
};

export type TokenCounts = {
  /** Uncached input tokens. For OpenAI-style usage, subtract cached_input_tokens first. */
  input: number;
  /** Output tokens. For OpenAI-style usage, add reasoning_output_tokens (billed as output). */
  output: number;
  cache_read?: number;
  /** 5-minute cache writes. */
  cache_write?: number;
  /** 1-hour cache writes. Only priced where the row has cache_write_1h. */
  cache_write_1h?: number;
  /**
   * Total input of one request: input + cache_read + cache_write + cache_write_1h.
   * Tiered rows (Haiku 5.5 above 100k tokens) need it, so pass a single request's counts.
   * Sum the per-request results for a session.
   */
  prompt_tokens?: number;
};

export type PriceResult = {
  usd: number | null;
  row_id: string;
};

const ROWS = rows.rows as PriceRow[];

// Bedrock regional and multi-region endpoints cost 10% more than global ones
// (platform.claude.com/docs/en/about-claude/pricing, "Regional and multi-region endpoint pricing").
const REGIONAL_PREFIXES = new Set(["us", "eu", "jp", "au", "apac"]);
const REGIONAL_PREMIUM = 1.1;

/**
 * Reduces a model id to its base name, e.g.
 *   "us.anthropic.claude-opus-5-5-v1:0" -> { base: "claude-opus-5-5", regional: true }
 *   "claude-opus-5-5[1m]"               -> { base: "claude-opus-5-5", regional: false }
 *   "global.anthropic.claude-haiku-5-5" -> { base: "claude-haiku-5-5", regional: false }
 *   "claude-sonnet-5-5-20260601"        -> { base: "claude-sonnet-5-5", regional: false }
 */
export function normaliseModelId(model: string): { base: string; regional: boolean } {
  let id = model.trim().toLowerCase();
  id = id.replace(/\[[^\]]*\]$/, "");
  let regional = false;
  for (;;) {
    const m = id.match(/^([a-z]+)\./);
    if (!m) break;
    const prefix = m[1] ?? "";
    if (prefix === "global") regional = false;
    else if (REGIONAL_PREFIXES.has(prefix)) regional = true;
    else if (prefix !== "anthropic") break;
    id = id.slice(m[0].length);
  }
  id = id.replace(/-v\d+(:\d+)?$/, "");
  id = id.replace(/-\d{8}$/, "").replace(/-\d{4}-\d{2}-\d{2}$/, "");
  return { base: id, regional };
}

function pickRow(base: string, promptTokens: number | undefined): PriceRow | "ambiguous" | undefined {
  const candidates = ROWS.filter((r) => r.model_pattern === base);
  if (candidates.length === 0) return undefined;
  if (candidates.length === 1) return candidates[0];
  if (promptTokens === undefined) return "ambiguous";
  return candidates.find(
    (r) =>
      (r.max_prompt_tokens === undefined || promptTokens <= r.max_prompt_tokens) &&
      (r.min_prompt_tokens === undefined || promptTokens >= r.min_prompt_tokens),
  );
}

/** Prices one token-count record for a model. Returns usd: null when the model or price is unknown. */
export function priceSession(model: string, tokens: TokenCounts): PriceResult {
  const { base, regional } = normaliseModelId(model);
  const row = pickRow(base, tokens.prompt_tokens);
  if (row === undefined) return { usd: null, row_id: "unknown" };
  if (row === "ambiguous") return { usd: null, row_id: "unknown" };

  const counts: [number, number | null | undefined][] = [
    [tokens.input, row.input],
    [tokens.output, row.output],
    [tokens.cache_read ?? 0, row.cache_read],
    [tokens.cache_write ?? 0, row.cache_write],
    [tokens.cache_write_1h ?? 0, row.cache_write_1h],
  ];
  let usd = 0;
  for (const [count, price] of counts) {
    if (count === 0) continue;
    if (price === null || price === undefined) return { usd: null, row_id: row.id };
    usd += (count * price) / 1_000_000;
  }
  return { usd: regional ? usd * REGIONAL_PREMIUM : usd, row_id: row.id };
}

#!/usr/bin/env bun
// Roster's command line. Each command lives in src/cli/<cmd>.ts and exports a Command; register it in COMMANDS below.
// See docs/DESIGN.md §"CLI".
import { reviewCommand } from "./cli/review.ts";

export interface Command {
  name: string;
  summary: string;
  usage: string;
  /** Runs the command with the arguments after its name. Resolves to the process exit code. */
  run: (args: string[]) => Promise<number>;
}

export const COMMANDS: readonly Command[] = [reviewCommand];

function printUsage(out: (s: string) => void): void {
  out("usage: roster <command> [args]\n");
  out("commands:");
  for (const c of COMMANDS) out(`  ${c.name.padEnd(10)} ${c.summary}`);
}

/** Dispatches argv (without the runtime and script path) to a command. Resolves to the exit code. */
export async function main(argv: string[]): Promise<number> {
  const [name, ...rest] = argv;
  if (name === undefined) {
    printUsage((s) => console.error(s));
    return 2;
  }
  if (name === "--help" || name === "-h" || name === "help") {
    printUsage((s) => console.log(s));
    return 0;
  }
  const cmd = COMMANDS.find((c) => c.name === name);
  if (!cmd) {
    console.error(`roster: unknown command "${name}"\n`);
    printUsage((s) => console.error(s));
    return 2;
  }
  if (rest.includes("--help") || rest.includes("-h")) {
    console.log(cmd.usage);
    return 0;
  }
  try {
    return await cmd.run(rest);
  } catch (err) {
    console.error(`roster ${cmd.name}: ${err instanceof Error ? err.message : String(err)}`);
    return 1;
  }
}

if (import.meta.main) {
  process.exitCode = await main(process.argv.slice(2));
