export function runGit(cwd: string, args: string[]): string {
  const r = Bun.spawnSync(["git", ...args], { cwd, env: gitEnv() });
  if (r.exitCode !== 0) throw new Error(`git ${args.join(" ")} failed: ${r.stderr.toString().trim()}`);
